import json

with open('/app/output/analysis_results.json') as f:
    stats = json.load(f)
with open('/app/output/charts.json') as f:
    charts = json.load(f)

# Format decade stats table rows
decade_rows = ""
for d in stats['decade_stats']:
    decade_rows += f"""
        <tr>
            <td>{int(d['Decade'])}s</td>
            <td>${d['mean']:.2f}</td>
            <td>${d['std']:.2f}</td>
            <td>${d['min']:.2f}</td>
            <td>${d['max']:.2f}</td>
            <td>{d['cv']:.2f}</td>
        </tr>"""

# Format shock events list (top 10 by abs MoM)
shocks = stats['shocks']
# deduplicate by date and sort by abs MoM
seen = set()
unique_shocks = []
for s in shocks:
    d = s['Date'][:10]
    if d not in seen:
        seen.add(d)
        unique_shocks.append(s)
unique_shocks.sort(key=lambda x: abs(x['MoM_pct']), reverse=True)
shock_rows = ""
for s in unique_shocks[:12]:
    mom = s['MoM_pct']
    yoy = s['YoY_pct']
    shock_rows += f"""
        <tr>
            <td>{s['Date'][:10]}</td>
            <td>${s['Crude_Oil_Price']:.2f}</td>
            <td class="{'up' if mom>=0 else 'down'}">{mom:+.1f}%</td>
            <td class="{'up' if yoy>=0 else 'down'}">{yoy:+.1f}%</td>
        </tr>"""

